package com.curso.security;
import com.curso.config.JwtProperties;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Date;
@Service public class JwtService{private final JwtProperties p;private final SecretKey key;public JwtService(JwtProperties p){this.p=p;this.key=Keys.hmacShaKeyFor(p.secret().getBytes(StandardCharsets.UTF_8));}public String emitir(String email){Instant now=Instant.now();return Jwts.builder().subject(email).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(p.expirationSeconds()))).signWith(key).compact();}public String validar(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();}public long expiracao(){return p.expirationSeconds();}}
